def _escribir_salida_arreglada(salida_normal, evento):
    """Arregla la salida del candado antes de copiarla. Nunca lanza.

    Motivo: Codex solo entiende el contexto adicional si va dentro de
    hookSpecificOutput con su hookEventName; si el candado lo deja arriba
    o sin evento, se pierde. Si no se puede leer como JSON o el evento
    esta vacio, se copia tal cual como antes.
    """
    if not evento:
        _escribir_texto(salida_normal)
        return
    try:
        datos = json.loads(salida_normal)
    except Exception:
        _escribir_texto(salida_normal)
        return
    if not isinstance(datos, dict):
        _escribir_texto(salida_normal)
        return
    hso = datos.get("hookSpecificOutput")
    if isinstance(hso, dict):
        if not hso.get("hookEventName"):
            hso["hookEventName"] = evento
    elif "additionalContext" in datos:
        contexto = datos.pop("additionalContext")
        datos["hookSpecificOutput"] = {
            "hookEventName": evento,
            "additionalContext": contexto,
        }
    _escribir_json(datos)
